class Solution {
public:
    ListNode* frequenciesOfElements(ListNode* head) {
        unordered_map<int, int> freq;
        ListNode* curr = head;
        while (curr) {
            freq[curr->val]++;
            curr = curr->next;
        }
        ListNode dummy(0);
        ListNode* tail = &dummy;
        for (auto& [val, count] : freq) {
            tail->next = new ListNode(count);
            tail = tail->next;
        }
        return dummy.next;
    }
};

class Solution {
    public ListNode frequenciesOfElements(ListNode head) {
        Map<Integer, Integer> freq = new HashMap<>();
        ListNode curr = head;
        while (curr != null) {
            freq.put(curr.val, freq.getOrDefault(curr.val, 0) + 1);
            curr = curr.next;
        }
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (int count : freq.values()) {
            tail.next = new ListNode(count);
            tail = tail.next;
        }
        return dummy.next;
    }
}

var frequenciesOfElements = function(head) {
    const freq = new Map();
    let curr = head;
    while (curr) {
        freq.set(curr.val, (freq.get(curr.val) || 0) + 1);
        curr = curr.next;
    }
    const dummy = new ListNode(0);
    let tail = dummy;
    for (const count of freq.values()) {
        tail.next = new ListNode(count);
        tail = tail.next;
